            add(RawHubEntry("flyfish", "Flyfish", "v1.0.3-365b2e2", "delirioux", "delirioux/flyfish", FirmwareCategory.FM_SYNTH, "Экспериментальный инструмент", "[Экспериментальный инструмент] One piece on the FM-1: Chopin's Étude Op. 10 No. 1 on a sampled Steinway D. It plays the étude, lets you shape it with rubato, touch and accents, practise it and move it. Built on Tuna and Felucca.", "One piece on the FM-1: Chopin's Étude Op. 10 No. 1 on a sampled Steinway D. It plays the étude, lets you shape it with rubato, touch and accents, practise it and move it. Built on Tuna and Felucca.", "FM-1_900", "fw/flyfish-1.0.3-777fa1c.fwsc", "d44d6b1b0eeb547fd590b882747f880ca271585a4cb434b2fe497f03d9080694", 610090, 2, 16, "2026-10-29", "2026-10-20", "GPL-3.0", false, false, false, false, false, "https://delirioux.github.io/flyfish/try/", ""))
            add(RawHubEntry("fmdj", "FMDj", "v2026.10.22", "DEADACTIVE", "DeadActive/FMDj", FirmwareCategory.CHIPTUNE, "Трекер", "[Трекер] Game Boy music programs on the FM-1: LSDj, the tracker, and DMGo!, the drum machine, in a Game Boy emulator on its screen, keys and knobs. Bring your own ROM: the install page puts it in, in your browser.", "Game Boy music programs on the FM-1: LSDj, the tracker, and DMGo!, the drum machine, in a Game Boy emulator on its screen, keys and knobs. Bring your own ROM: the install page puts it in, in your browser.", "FM-1_900", "fw/fmdj-2026.10.22.fwsc", "857bd4fafca1fb78ac47386b5c02ab58acd8c72ca69ce341461f188c49b68342", 609849, 2, 0, "2026-10-22", "2026-10-29", "GPL-3.0", false, false, false, false, false, "", ""))
            add(RawHubEntry("modelar", "MODELAR", "v0.3", "Hirakos", "hirakos999/MODELAR", FirmwareCategory.AMBIENT, "Синтезатор · Эмбиент и дрон", "[Синтезатор · Эмбиент и дрон] A semi-modular drone synth played like a Kaoss Pad: four oscillators modulating each other through eight routings, and keys that move a cursor on an XY pad instead of playing notes: white keys are points, black keys gestures. ARP, a polymetric sequencer, a clock in Hz and eight generative environments.", "A semi-modular drone synth played like a Kaoss Pad: four oscillators modulating each other through eight routings, and keys that move a cursor on an XY pad instead of playing notes: white keys are points, black keys gestures. ARP, a polymetric sequencer, a clock in Hz and eight generative environments.", "FM-1_42000300", "fw/modelar-0.3.fwsc", "14de4b6efdc5550149fe745158b22929d13fcfa6268bc751ace7eb27f21ffeac", 610136, 1, 74, "2026-10-22", "2026-10-22", "MPL-2.0", false, false, true, false, false, "", ""))
            add(RawHubEntry("opn1", "OPN-1", "v2.0.0", "putchdev", "putchdev/opn-1", FirmwareCategory.CHIPTUNE, "Синтезатор · Винтажная эмуляция", "[Синтезатор · Винтажная эмуляция] The Sega Genesis / Mega Drive's Yamaha YM2612: six channels of 4-operator FM. Its web app takes patches from game music (VGM) and OPM files and streams VGM tunes to the FM-1 to play.", "The Sega Genesis / Mega Drive's Yamaha YM2612: six channels of 4-operator FM. Its web app takes patches from game music (VGM) and OPM files and streams VGM tunes to the FM-1 to play.", "FM-1_950", "fw/opn1-2.0.0.fwsc", "31b88c6fd4ec081ce85393977453e61ff86c6f545f10e7b1db2023986803675c", 610110, 1, 72, "2026-10-17", "2026-10-19", "GPL-3.0", false, false, false, false, false, "", ""))
