            add(RawHubEntry("fm1sid", "FM-1 SID", "v0.3", "Joakim Eriksson", "joakimeriksson/fm1-sid", FirmwareCategory.CHIPTUNE, "Трекер · Винтажная эмуляция", "Эмуляция звукового чипа Commodore 64 MOS 6581/8580 SID с кольцевой модуляцией, синхронизацией осцилляторов и табличным арпеджио. (C64 music on the FM-1: a 6510 runs each tune's own code and reSID plays it, PSID and RSID. A GoatTracker 2 editor on the FM-1 itself with ten GT2 example songs, a SID synth with a sequencer and effects, and any .sid sent from the browser plays at once.)", "C64 music on the FM-1: a 6510 runs each tune's own code and reSID plays it, PSID and RSID. A GoatTracker 2 editor on the FM-1 itself with ten GT2 example songs, a SID synth with a sequencer and effects, and any .sid sent from the browser plays at once.", "FM-1_900", "fw/fm1sid-0.3.fwsc", "30fbbeb839e34eb9cd06b543b9142cce3a937d6b0a221e9985412cebba324ed3", 610110, 1, 7, "2026-10-25", "2026-11-01", "GPL-3.0", false, false, true, false, false, "https://joakimeriksson.github.io/fm1-emu/fm1-sid/", ""))
            add(RawHubEntry("fm1trax", "FM1-TRAX", "v0.9.3", "jartificer", "jartificer/fm1-trax", FirmwareCategory.CHIPTUNE, "Трекер", "Вертикальный 4-канальный трекер в духе Amiga ProTracker / FastTracker с шестнадцатеричным вводом нот и эффектов. (A Mega Drive / Genesis music tracker. It emulates the YM2612 and SN76489 chips: six FM channels, three square waves and noise, with Deflemask-style effects, 128 FM presets, a drum kit on the DAC, 256 song slots, a demo song and VGM export.)", "A Mega Drive / Genesis music tracker. It emulates the YM2612 and SN76489 chips: six FM channels, three square waves and noise, with Deflemask-style effects, 128 FM presets, a drum kit on the DAC, 256 song slots, a demo song and VGM export.", "FM-1_601", "fw/fm1trax-0.9.3.fwsc", "ae14c3594542808f1367927b8b382e4b7930a8ff68e540d2bb037513b07736e1", 609661, 1, 6, "2026-11-01", "2026-11-01", "GPL-3.0", false, false, true, false, false, "https://jartificer.github.io/fm1-trax/", "https://jartificer.github.io/fm1-trax/editor.html"))
            add(RawHubEntry("amenity", "Amenity", "v1.0.0", "Presethead", "ejtb76/amenity", FirmwareCategory.GROOVEBOX, "Драм-машина / Сэмплер", "[Драм-машина / Сэмплер] A live jungle tool built around the Amen break. Hold white keys for rolls, builds, echo and Akai-style metallic stretch, play hits on the black keys, and shape the break with variation, warp, ringing feedback, lo-fi, EQ, saturation and compression.", "A live jungle tool built around the Amen break. Hold white keys for rolls, builds, echo and Akai-style metallic stretch, play hits on the black keys, and shape the break with variation, warp, ringing feedback, lo-fi, EQ, saturation and compression.", "FM-1_8170001", "fw/amenity-1.0.0.fwsc", "eb7f77948cd93ad4bbd0c3d5661ee83b3e6d7d524c9be78dbde2ba330f4f8e52", 487988, 1, 3, "2026-11-01", "2026-11-01", "GPL-3.0 + SDK exception", false, false, false, false, false, "", ""))
            add(RawHubEntry("fizz", "FIZZ", "v0.12.0-beta.12", "Quixotic7", "Quixotic7/FIZZ", FirmwareCategory.GROOVEBOX, "Грувбокс", "[Грувбокс] A groovebox around one engine, ChoralRoot's FM TONE: eight tracks, p-locks and preset sound locks, conditions, ratchets, chords, and MIDI FX for generative patterns and for reworking the ones you have. Bluetooth MIDI, and recording over USB audio.", "A groovebox around one engine, ChoralRoot's FM TONE: eight tracks, p-locks and preset sound locks, conditions, ratchets, chords, and MIDI FX for generative patterns and for reworking the ones you have. Bluetooth MIDI, and recording over USB audio.", "FM-1_46001200", "fw/fizz-0.12.0-beta.12.fwsc", "931df76eb1a966270b8551cd642dd8f85ebad81d1a770ec38959b23b79c62385", 611496, 1, 0, "2026-10-28", "2026-10-25", "MPL-2.0", false, false, true, false, false, "https://quixotic7.github.io/FIZZ/", "https://quixotic7.github.io/FIZZ/manager/"))
            add(RawHubEntry("lsdjburrito", "LSDJ Burrito", "v0.9.96", "Dreamy_bacon", "dreamsofbacon/lsdj-burrito-src", FirmwareCategory.CHIPTUNE, "Трекер", "[Трекер] Little Sound Dj, the Game Boy tracker, on the FM-1: played from its keys and knobs, with per-channel filters, drive, lo-fi and an LFO, a shared echo and compressor, MIDI sync and colour themes. Bring your own LSDj: the project's web page adds it to this firmware on your computer.", "Little Sound Dj, the Game Boy tracker, on the FM-1: played from its keys and knobs, with per-channel filters, drive, lo-fi and an LFO, a shared echo and compressor, MIDI sync and colour themes. Bring your own LSDj: the project's web page adds it to this firmware on your computer.", "FM-1_537000996", "fw/lsdjburrito-0.9.96.fwsc", "dfbd44cf17f042d6f4d14cb9586ee6f520e85a1e5686defb0e00933b119bb044", 610089, 1, 0, "2026-10-31", "2026-10-31", "GPL-3.0", false, false, true, false, false, "https://dreamsofbacon.github.io/lsdj-burrito/#emulator-sec", "https://dreamsofbacon.github.io/lsdj-burrito/#connect"))
            add(RawHubEntry("bunker", "Bunker Evolved", "v1.0.0", "Kid Bunka", "kidbee85-beep/bunker-evolved", FirmwareCategory.AMBIENT, "Синтезатор · Эмбиент и дрон", "[Синтезатор · Эмбиент и дрон] Generative ambient: four editable layers from 64 sound recipes, 24 worlds, 24 motifs and 32 scales. GROW varies the phrases, seven EVOLVE processes change them over time. Felucca's sound pages stay. Built on Felucca 1.6.1.", "Generative ambient: four editable layers from 64 sound recipes, 24 worlds, 24 motifs and 32 scales. GROW varies the phrases, seven EVOLVE processes change them over time. Felucca's sound pages stay. Built on Felucca 1.6.1.", "FM-1_7100002", "fw/bunker-1.0.0.fwsc", "db0b50d0ae9c3bfccee76e3b93de09fffa55389169278a0c5899dad9c79e6bb8", 610090, 0, 118, "2026-10-17", "2026-10-19", "GPL-3.0", false, false, false, false, false, "https://bunker-evolved.sugarypixie10.chatgpt.site/simulator/", "https://bunker-evolved.sugarypixie10.chatgpt.site/editor/"))
            add(RawHubEntry("delrio", "Del Rio", "v1.0", "Jess Del Rio", "jsopdebeeck/fm1-delrio", FirmwareCategory.GROOVEBOX, "Драм-машина / Сэмплер", "[Драм-машина / Сэмплер] A rhythm box of ceremony percussion: djembe, cajon, udu, clapsticks, maracas and triangle, their real strokes on the black keys, a step sequencer on the white keys and 31 rhythms from the literature. Played alone: a berimbau with its caxixi, a buzzing tanpura and a breathing shruti box. Built on fm1-base.", "A rhythm box of ceremony percussion: djembe, cajon, udu, clapsticks, maracas and triangle, their real strokes on the black keys, a step sequencer on the white keys and 31 rhythms from the literature. Played alone: a berimbau with its caxixi, a buzzing tanpura and a breathing shruti box. Built on fm1-base.", "FM-1_48010000", "fw/delrio-1.0.fwsc", "3bcff066a91c221f79c335569c0330fd80f4da262a764e56a9d0a56d4a41aff2", 611354, 0, 82, "2026-11-01", "2026-10-24", "MPL-2.0", false, false, false, false, false, "", ""))
            add(RawHubEntry("sid1", "SID-1", "v1.0.0", "putchdev", "putchdev/sid-1", FirmwareCategory.CHIPTUNE, "Синтезатор · Винтажная эмуляция", "[Синтезатор · Винтажная эмуляция] The Commodore 64's SID chip, twice for six voices. Its web app edits patches and takes them straight from .sid game music files.", "The Commodore 64's SID chip, twice for six voices. Its web app edits patches and takes them straight from .sid game music files.", "FM-1_960", "fw/sid1-1.0.0.fwsc", "4ee3dbe2079ea066e33a3843ec8e508e9eab191a500cad4944e00fd603683838", 610110, 0, 78, "2026-10-17", "2026-10-19", "GPL-3.0", false, false, false, false, false, "", ""))
