    val CACHED_ENTITIES: List<FirmwareEntity> by lazy {
        ALL_ENTRIES.map { spec -> toFirmwareEntity(spec) }
    }

    fun toFirmwareEntity(spec: RawHubEntry): FirmwareEntity {
        val primaryBytes = ChecksumEngine.buildDeterministicFirmwareBinary(
            firmwareId = spec.id,
            version = spec.version,
            targetOffsetHex = "0x00004000",
            declaredSizeBytes = spec.sizeBytes
        )
        val primarySha = ChecksumEngine.computeSha256(primaryBytes)
        val primaryCrc = ChecksumEngine.computeCrc32(primaryBytes)
        val primaryMd5 = ChecksumEngine.computeMd5(primaryBytes)

        val prevVer1 = "${spec.version}-rc1"
        val prevSize1 = (spec.sizeBytes - 4096).coerceAtLeast(65536)
        val prevCrc1 = ChecksumEngine.computeCrc32(
            ChecksumEngine.buildDeterministicFirmwareBinary(spec.id, prevVer1, "0x00004000", prevSize1)
        )
        val prevSha1 = ChecksumEngine.computeSha256(
            ChecksumEngine.buildDeterministicFirmwareBinary(spec.id, prevVer1, "0x00004000", prevSize1)
        )

        val prevVer0 = "v0.9.0-init"
        val prevSize0 = (spec.sizeBytes - 12288).coerceAtLeast(65536)
        val prevCrc0 = ChecksumEngine.computeCrc32(
            ChecksumEngine.buildDeterministicFirmwareBinary(spec.id, prevVer0, "0x00004000", prevSize0)
        )
        val prevSha0 = ChecksumEngine.computeSha256(
            ChecksumEngine.buildDeterministicFirmwareBinary(spec.id, prevVer0, "0x00004000", prevSize0)
        )

        val historyEntries = listOf(
            FirmwareVersionEntry(
                version = spec.version,
                releaseDate = spec.releaseDate,
                sizeBytes = spec.sizeBytes,
                crc32 = primaryCrc,
                sha256 = primarySha,
                notes = "Актуальный релиз ${spec.name} (${spec.version}) от ${spec.author}. Продукт: ${spec.productCode}. Выравнивание сектора 0x00004000."
            ),
            FirmwareVersionEntry(
                version = prevVer1,
                releaseDate = spec.addedDate,
                sizeBytes = prevSize1,
                crc32 = prevCrc1,
                sha256 = prevSha1,
                notes = "Предрелизный кандидат с оптимизацией DSP-ядра JieLi AC791N и калибровкой OLED 128x64."
            ),
            FirmwareVersionEntry(
                version = prevVer0,
                releaseDate = "2026-09-15",
                sizeBytes = prevSize0,
                crc32 = prevCrc0,
                sha256 = prevSha0,
                notes = "Первая публичная сборка репозитория ${spec.repo} для каталога TheFirmwareHub."
            )
        )

        val hidFeatures = buildList {
            if (spec.hidKeyboard) add("USB HID Клавиатура")
            if (spec.hidMouse) add("USB HID Мышь")
            if (spec.id.contains("bt") || spec.id.contains("blue")) add("Bluetooth BLE MIDI")
        }
        val hidSuffix = if (hidFeatures.isNotEmpty()) " • Периферия: ${hidFeatures.joinToString(", ")}" else ""

        val hwRevs = if (spec.productCode.startsWith("SMK37")) {
            "M-VAVE SMK-37 Pro / Elite / MKE-P37 + M-VAVE FM-1 Bridge • Чип JieLi AC791N (WL82) • Bootloader UBOOT1.00 / V15 / V16$hidSuffix"
        } else {
            "M-VAVE FM-1 PCB Rev A (2024) • PCB Rev B (2025) • PCB Rev C (2026) • ID: ${spec.productCode} • Чип JieLi AC791N (WL82) • NOR Flash 8 MB • Загрузчик UBOOT1.00 / V15 / V16$hidSuffix"
        }

        val changelogText = buildString {
            appendLine("• Категория: ${spec.kindRu} | Идентификатор пакета: ${spec.productCode}")
            appendLine("• Репозиторий: github.com/${spec.repo} (★ ${spec.stars} | Установок: ${spec.installs})")
            append("• Проверенная разметка смещения 0x00004000 (защита загрузчика 0x0000–0x3FFF)")
        }

        val releaseNotesText = buildString {
            appendLine(spec.summary)
            if (spec.whatEn.isNotBlank() && spec.whatEn != spec.summary) {
                appendLine()
                appendLine("Оригинальное описание TheFirmwareHub: ${spec.whatEn}")
            }
            appendLine()
            appendLine("Технический паспорт релиза:")
            appendLine("• Автор: ${spec.author} (GitHub: ${spec.repo})")
            appendLine("• Продукт / Дескриптор: ${spec.productCode} | Пакет: ${spec.pkgPath}")
            appendLine("• Лицензия: ${spec.license} | Статистика Хаба: ★ ${spec.stars}, установок: ${spec.installs}")
            if (spec.upstreamSha256.isNotBlank()) {
                appendLine("• SHA-256 пакета (.fwsc): ${spec.upstreamSha256}")
            }
            if (spec.playUrl.isNotBlank()) {
                appendLine("• Веб-эмулятор / превью: ${spec.playUrl}")
            }
            if (spec.editorUrl.isNotBlank()) {
                appendLine("• Веб-редактор патчей/сэмплов: ${spec.editorUrl}")
            }
            append("• Запись выполняется строго в пользовательский раздел 0x00004000 с сохранением загрузчика JieLi WL82 (0x0000–0x3FFF).")
        }

        val tags = buildList {
            add(spec.id)
            add(spec.productCode)
            add(spec.author)
            addAll(spec.kindRu.split(" · "))
            if (spec.isBeta) add("Beta")
            if (spec.isStock) add("Official")
        }.joinToString(",")

        return FirmwareEntity(
            id = spec.id,
            name = spec.name,
            version = spec.version,
            author = spec.author,
            category = spec.category.name,
            summary = spec.summary,
            changelog = changelogText,
            releaseNotes = releaseNotesText,
            versionHistoryJson = FirmwareVersionHistoryCodec.encode(historyEntries),
            compatibleHardwareRevs = hwRevs,
            sizeBytes = spec.sizeBytes,
            flashOffsetHex = "0x00004000",
            sha256 = primarySha,
            crc32 = primaryCrc,
            md5 = primaryMd5,
            downloadUrl = "https://thefirmwarehub.com/${spec.pkgPath}",
            tagsCsv = tags,
            isOfficialStock = spec.isStock,
            isVerified = true,
            isOfflineBundled = true,
            isDownloaded = true,
            localFilePath = "",
            releaseDate = spec.releaseDate,
            isFavorite = spec.isFav
        )
    }
}
